/*gen:code:trie_console*/ const CODE_trie_console = "#include <algorithm>\n#include <array>\n#include <cstdio>\n#include <string>\n#include <vector>\n\n// A trie for console commands: lowercase letters and '_' (27 symbols).\n// Nodes live in one std::vector (a pool) and refer to children by index,\n// so there is no new/delete per node and the nodes sit close in memory.\nclass Trie {\npublic:\n    Trie() { nodes_.emplace_back(); }          // node 0 is the root (empty prefix)\n\n    void insert(const std::string& word) {\n        int v = 0;\n        for (char ch : word) {\n            int c = slot(ch);\n            if (nodes_[v].next[c] == 0) {            // 0 = \"no child\" (root is never a child)\n                nodes_[v].next[c] = static_cast<int>(nodes_.size());\n                nodes_.emplace_back();               // may reallocate: use indices, not references\n            }\n            v = nodes_[v].next[c];\n        }\n        nodes_[v].terminal = true;\n    }\n    bool contains(const std::string& word) const {\n        int v = find(word);\n        return v >= 0 && nodes_[v].terminal;\n    }\n    // Every stored word that starts with `prefix`, in alphabetical order.\n    std::vector<std::string> complete(const std::string& prefix) const {\n        std::vector<std::string> out;\n        int v = find(prefix);\n        if (v >= 0) {\n            std::string buf = prefix;\n            collect(v, buf, out);\n        }\n        return out;\n    }\n    std::size_t node_count() const { return nodes_.size(); }\n\nprivate:\n    struct Node {\n        std::array<int, 27> next{};    // child index per symbol, 0 = none\n        bool terminal = false;         // a word ends here\n    };\n    std::vector<Node> nodes_;\n\n    static int slot(char ch) { return ch == '_' ? 26 : ch - 'a'; }\n    static char symbol(int c) { return c == 26 ? '_' : static_cast<char>('a' + c); }\n\n    int find(const std::string& s) const {      // node for prefix s, or -1\n        int v = 0;\n        for (char ch : s) {\n            v = nodes_[v].next[slot(ch)];\n            if (v == 0) return -1;\n        }\n        return v;\n    }\n    void collect(int v, std::string& buf, std::vector<std::string>& out) const {\n        if (nodes_[v].terminal) out.push_back(buf);\n        for (int c = 0; c < 27; ++c)            // children in symbol order: a..z, then '_'\n            if (int w = nodes_[v].next[c]) {\n                buf.push_back(symbol(c));\n                collect(w, buf, out);\n                buf.pop_back();\n            }\n    }\n};\n\nvoid show(const char* prefix, const std::vector<std::string>& words) {\n    std::printf(\"%-5s ->\", prefix);\n    for (const auto& w : words) std::printf(\" %s\", w.c_str());\n    std::printf(\"%s\\n\", words.empty() ? \" (none)\" : \"\");\n}\n\nint main() {\n    std::vector<std::string> commands{\"god\", \"give\", \"give_ammo\", \"goto\", \"gravity\",\n                                      \"kick\", \"kill\", \"kill_all\", \"map\", \"map_list\", \"noclip\"};\n    Trie t;\n    for (const auto& c : commands) t.insert(c);\n    std::printf(\"%zu commands, %zu trie nodes\\n\", commands.size(), t.node_count());\n    for (const char* p : {\"gi\", \"kil\", \"map\", \"x\"}) show(p, t.complete(p));\n    std::printf(\"contains(\\\"kil\\\") = %d, contains(\\\"kill\\\") = %d\\n\", t.contains(\"kil\"), t.contains(\"kill\"));\n\n    // The standard-library alternative: a sorted vector. All words with a given\n    // prefix form one contiguous run that starts at lower_bound(prefix).\n    std::sort(commands.begin(), commands.end());\n    std::string p = \"gi\";\n    auto it = std::lower_bound(commands.begin(), commands.end(), p);\n    std::printf(\"sorted vector, \\\"gi\\\":\");\n    for (; it != commands.end() && it->compare(0, p.size(), p) == 0; ++it) std::printf(\" %s\", it->c_str());\n    std::printf(\"\\n\");\n}";
