/*gen:code:segtree_min*/ const CODE_segtree_min = "#include <algorithm>\n#include <climits>\n#include <cstdio>\n#include <vector>\n\n// Range-minimum segment tree with point updates (recursive).\n// Node v covers a[lo..hi]; its children are 2v (left half) and 2v+1 (right half).\nclass MinSegTree {\npublic:\n    explicit MinSegTree(const std::vector<int>& a) : n_(static_cast<int>(a.size())), t_(4 * a.size()) {\n        build(1, 0, n_ - 1, a);\n    }\n    void set(int i, int value) { update(1, 0, n_ - 1, i, value); }\n    int min(int l, int r) { visited = 0; return query(1, 0, n_ - 1, l, r); }   // inclusive l..r\n    int visited = 0;\n\nprivate:\n    int n_;\n    std::vector<int> t_;   // 4n is always enough for this recursive layout\n\n    void build(int v, int lo, int hi, const std::vector<int>& a) {\n        if (lo == hi) { t_[v] = a[lo]; return; }\n        int mid = lo + (hi - lo) / 2;\n        build(2 * v, lo, mid, a);\n        build(2 * v + 1, mid + 1, hi, a);\n        t_[v] = std::min(t_[2 * v], t_[2 * v + 1]);\n    }\n    void update(int v, int lo, int hi, int i, int value) {\n        if (lo == hi) { t_[v] = value; return; }\n        int mid = lo + (hi - lo) / 2;\n        if (i <= mid) update(2 * v, lo, mid, i, value);\n        else update(2 * v + 1, mid + 1, hi, i, value);\n        t_[v] = std::min(t_[2 * v], t_[2 * v + 1]);   // recompute on the way back up\n    }\n    int query(int v, int lo, int hi, int l, int r) {\n        ++visited;\n        if (r < lo || hi < l) return INT_MAX;          // disjoint: identity for min\n        if (l <= lo && hi <= r) return t_[v];          // fully inside: use the stored answer\n        int mid = lo + (hi - lo) / 2;                  // partial overlap: ask both halves\n        return std::min(query(2 * v, lo, mid, l, r), query(2 * v + 1, mid + 1, hi, l, r));\n    }\n};\n\nint main() {\n    // Hit points of a squad of 8 units, in formation order.\n    std::vector<int> hp{90, 75, 40, 100, 65, 80, 55, 95};\n    MinSegTree tree(hp);\n    int low = tree.min(1, 5);\n    std::printf(\"lowest HP in units 1..5: %d (visited %d nodes)\\n\", low, tree.visited);\n    tree.set(4, 30);                                   // unit 4 takes a hit\n    low = tree.min(1, 5);\n    std::printf(\"after hit, units 1..5:   %d (visited %d nodes)\\n\", low, tree.visited);\n    low = tree.min(0, 7);\n    std::printf(\"whole squad:             %d (visited %d node)\\n\", low, tree.visited);\n\n    // Worst case over ALL ranges [l, r], for growing n: about 4 log2(n) nodes.\n    for (int n : {8, 64, 1024}) {\n        MinSegTree big(std::vector<int>(n, 1));\n        int worst = 0;\n        for (int l = 0; l < n; ++l)\n            for (int r = l; r < n; ++r) {\n                big.min(l, r);\n                worst = std::max(worst, big.visited);\n            }\n        std::printf(\"n = %4d: at most %2d nodes visited\\n\", n, worst);\n    }\n}";
