/*gen:code:segtree_iter*/ const CODE_segtree_iter = "#include <cstdio>\n#include <vector>\n\n// Bottom-up segment tree for sums: leaves at t[n..2n), node i has children 2i, 2i+1.\n// Works for any n (not just powers of two) with exactly 2n slots.\nstruct SumTree {\n    int n;\n    std::vector<long long> t;\n    explicit SumTree(const std::vector<long long>& a) : n(static_cast<int>(a.size())), t(2 * a.size()) {\n        for (int i = 0; i < n; ++i) t[n + i] = a[i];\n        for (int i = n - 1; i > 0; --i) t[i] = t[2 * i] + t[2 * i + 1];\n    }\n    void set(int i, long long value) {\n        for (t[i += n] = value; i > 1; i /= 2) t[i / 2] = t[i] + t[i ^ 1];   // i ^ 1 = sibling\n    }\n    long long sum(int l, int r) const {            // half-open [l, r)\n        long long s = 0;\n        for (l += n, r += n; l < r; l /= 2, r /= 2) {\n            if (l & 1) s += t[l++];                // l is a right child: take it, step right\n            if (r & 1) s += t[--r];                // r is a right child: its sibling r - 1 is inside\n        }\n        return s;\n    }\n};\n\nint main() {\n    SumTree st({5, 3, 7, 9, 6, 4, 1, 2});\n    std::printf(\"sum[2, 7) = %lld\\n\", st.sum(2, 7));   // 7 + 9 + 6 + 4 + 1\n    st.set(3, 2);\n    std::printf(\"after a[3] = 2: sum[2, 7) = %lld, total = %lld\\n\", st.sum(2, 7), st.sum(0, 8));\n}";
