/*gen:code:fenwick*/ const CODE_fenwick = "#include <cstdio>\n#include <vector>\n\n// Fenwick tree (binary indexed tree), 1-based: t[i] = a[i - lowbit(i) + 1] + ... + a[i].\nclass Fenwick {\npublic:\n    explicit Fenwick(int n) : n_(n), t_(n + 1, 0) {}\n    void add(int i, long long delta) {             // a[i] += delta\n        for (; i <= n_; i += i & -i) t_[i] += delta;\n    }\n    long long prefix(int i) const {                // a[1] + ... + a[i]\n        long long s = 0;\n        for (; i > 0; i -= i & -i) s += t_[i];\n        return s;\n    }\n    long long range(int l, int r) const { return prefix(r) - prefix(l - 1); }\n\nprivate:\n    int n_;\n    std::vector<long long> t_;\n};\n\nint main() {\n    // The lowbit trick: in two's complement, -i flips every bit above the lowest 1.\n    for (int i : {6, 7, 8, 12}) std::printf(\"lowbit(%2d) = %d\\n\", i, i & -i);\n\n    Fenwick f(8);\n    long long a[] = {0, 5, 3, 7, 9, 6, 4, 1, 2};   // a[1..8]; a[0] unused\n    for (int i = 1; i <= 8; ++i) f.add(i, a[i]);\n    std::printf(\"prefix(7) = %lld, range(3, 7) = %lld\\n\", f.prefix(7), f.range(3, 7));\n\n    // Leaderboard ranks: count players per score, rank = 1 + (players with a higher score).\n    const int MAX_SCORE = 1000;\n    Fenwick count(MAX_SCORE + 1);                  // score s is stored at index s + 1\n    std::vector<int> score{420, 870, 420, 990, 150, 610};\n    for (int s : score) count.add(s + 1, 1);\n    auto rank = [&](int s) { return 1 + count.range(s + 2, MAX_SCORE + 1); };\n    std::printf(\"player 0 (420) rank %lld, player 4 (150) rank %lld\\n\", rank(score[0]), rank(score[4]));\n    count.add(score[4] + 1, -1);                   // player 4 scores big: move them\n    score[4] = 900;\n    count.add(score[4] + 1, +1);\n    std::printf(\"player 4 (900) rank %lld, player 0 (420) rank %lld\\n\", rank(score[4]), rank(score[0]));\n}";
